//     {editOpen && <div className="mc-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setEditOpen(false) }}><div className="mc-modal mc-modal-wide" role="dialog" aria-modal="true" aria-label="Edit company details"><div className="mc-modal-head"><div><span className="mc-panel-eyebrow">COMPANY PROFILE</span><h3>Edit company details</h3><p>Update the information shown in your company workspace.</p></div><button className="mc-close" onClick={() => setEditOpen(false)}><X size={20} /></button></div><form onSubmit={save}><div className="mc-modal-scroll"><div className="mc-form-grid">{fieldDefs.map(([key, label]) => <label key={key} className={key === "registeredAddress" ? "mc-form-full" : ""}><span>{label}</span>{key === "jurisdiction" ? <select value={draft[key] || ""} onChange={e => setDraft(v => ({ ...v, [key]: e.target.value }))}><option value="">Select jurisdiction</option>{["Mainland", "Free Zone", "Offshore"].map(v => <option key={v}>{v}</option>)}</select> : key === "emirate" ? <select value={draft[key] || ""} onChange={e => setDraft(v => ({ ...v, [key]: e.target.value }))}><option value="">Select emirate</option>{["Abu Dhabi", "Dubai", "Sharjah", "Ajman", "Umm Al Quwain", "Ras Al Khaimah", "Fujairah"].map(v => <option key={v}>{v}</option>)}</select> : <input value={draft[key] || ""} onChange={e => setDraft(v => ({ ...v, [key]: e.target.value }))} placeholder={`Enter ${label.toLowerCase()}`} />}</label>)}</div><div className="mc-form-section">Registration information</div><div className="mc-form-grid">{[["registrationNumber", "Registration number"], ["licenceNumber", "Licence number"], ["incorporationDate", "Incorporation date"], ["licenceExpiry", "Licence expiry"]].map(([key, label]) => <label key={key}><span>{label}</span><input type={key.toLowerCase().includes("date") || key === "licenceExpiry" ? "date" : "text"} value={draft[key] || ""} onChange={e => setDraft(v => ({ ...v, [key]: e.target.value }))} /></label>)}</div><div className="mc-note"><LockKeyhole size={16} /> In a live portal, verified legal details should be reviewed before changing official records.</div>{error && <p className="mc-error">{error}</p>}</div><div className="mc-modal-footer"><button type="button" className="mc-outline" onClick={() => setEditOpen(false)}>Cancel</button><button type="submit" className="mc-primary" disabled={busy}>{busy ? "Saving..." : "Save changes"}<Check size={16} /></button></div></form></div></div>}
//     {uploadOpen && <div className="mc-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setUploadOpen(false) }}><div className="mc-modal" role="dialog" aria-modal="true" aria-label="Upload company documents"><div className="mc-modal-head"><div><span className="mc-panel-eyebrow">COMPANY FILES</span><h3>Upload documents</h3><p>Add PDFs, images or Word documents (up to 15 MB each).</p></div><button className="mc-close" onClick={() => setUploadOpen(false)}><X size={20} /></button></div><div className="mc-modal-scroll"><label className="mc-form-label">Document category<select value={uploadCategory} onChange={e => setUploadCategory(e.target.value)}>{docCategories.filter(c => c !== "All documents").map(c => <option key={c}>{c}</option>)}</select></label><button className="mc-dropzone" disabled={busy} onClick={() => fileRef.current?.click()}><span><Upload size={24} /></span><strong>{busy ? "Uploading..." : "Choose files to upload"}</strong><small>PDF, PNG, JPG, DOC, DOCX · Max 15 MB per file</small></button><input ref={fileRef} type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" hidden onChange={handleFiles} />{error && <p className="mc-error">{error}</p>}<div className="mc-note"><LockKeyhole size={16} /> Documents are only stored permanently when an upload backend is connected.</div></div><div className="mc-modal-footer"><button className="mc-outline" onClick={() => setUploadOpen(false)}>Close</button></div></div></div>}
